        m.put("scabarites", Arrays.asList("Scarab swarm", "Locust rider", "Scarab mage", "Small Scarab"));
        m.put("scorpions", Arrays.asList("Scorpia", "Lobstrosity"));
        m.put("shades", Arrays.asList("Loar", "Phrin", "Riyl", "Asyn", "Fiyr", "Urium"));
        m.put("skeletons", Arrays.asList("Vet'ion", "Calvar'ion", "Skeletal Mystic"));
        m.put("spiders", Arrays.asList("Kalrag", "Sarachnis", "Venenatis", "Spindel", "Araxxor", "Araxyte"));
        m.put("spiritual creatures", Arrays.asList("Spiritual ranger", "Spiritual mage", "Spiritual warrior"));
        m.put("trolls", Arrays.asList("Dad", "Arrg", "Stick", "Kraka", "Pee Hat", "Rock", "Twig", "Berry"));
        m.put("tzhaar", Arrays.asList("TzTok-Jad", "TzKal-Zuk"));
        m.put("vampyres", Arrays.asList("Vyrewatch"));
        m.put("warped creatures", Arrays.asList("Warped terrorbird", "Warped tortoise", "Mutated terrorbird", "Mutated tortoise"));
        m.put("werewolves", Arrays.asList("Werewolf"));
        m.put("wolves", Arrays.asList("Wolf"));
        m.put("wyrms", Arrays.asList("Wyrmling", "Strykewyrm"));
        m.put("zombies", Arrays.asList("Undead", "Vorkath", "Zogre"));

        TASK_ALIASES = Collections.unmodifiableMap(m);
    }

    private SlayerTaskTargets()
    {
    }

    /**
     * @return {@code true} if {@code npcName} satisfies the task named
     * {@code taskName}. Matching is case-insensitive and whole-word, exactly
     * matching the official Slayer plugin's behavior.
     */
    static boolean matches(String taskName, String npcName)
    {
        if (taskName == null || npcName == null)
        {
            return false;
        }

        String task = taskName.trim().toLowerCase(Locale.ROOT);
        String npc = npcName.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
        if (task.isEmpty() || npc.isEmpty())
        {
            return false;
        }

        for (Pattern target : TARGET_PATTERNS.computeIfAbsent(task, SlayerTaskTargets::buildTargetPatterns))
        {
            if (target.matcher(npc).find())
            {
                return true;
            }
        }
        return false;
    }

    /**
     * Compiles every target name for a task once. The task name is fixed for
     * the length of an assignment, so kills reuse the cached patterns rather
     * than recompiling them for each alias on every drop.
     */
    private static List<Pattern> buildTargetPatterns(String task)
    {
        List<Pattern> patterns = new ArrayList<>();

        // Singular form of the task name (e.g. "dogs" -> "dog") is always a
        // valid target, using the same rule the Slayer plugin applies in
        // rebuildTargetNames() with replaceAll("s$", "").
        addWholeWordPattern(patterns, task.replaceAll("s$", ""));

        List<String> aliases = TASK_ALIASES.get(task);
        if (aliases != null)
        {
            for (String alias : aliases)
            {
                addWholeWordPattern(patterns, alias.toLowerCase(Locale.ROOT));
            }
        }

        return Collections.unmodifiableList(patterns);
    }

    private static void addWholeWordPattern(List<Pattern> patterns, String needle)
    {
        if (needle == null || needle.isEmpty())
        {
            return;
        }

        // Same boundary semantics as SlayerPlugin#targetNamePattern:
        // (?:\s|^)<target>(?:\s|$), case-insensitive.
        String regex = "(?:\\s|^)" + Pattern.quote(needle) + "(?:\\s|$)";
        patterns.add(Pattern.compile(regex, Pattern.CASE_INSENSITIVE));
    }
}

package com.papabald.slayerloot;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Decides whether supplies used right now belong to the Slayer task.
 *
 * <p>A session opens on a task kill and stays open until no task kill has
 * happened for the idle timeout, so a bank trip or an unrelated activity
 * between kills isn't billed to the task. Supplies used while no session is
 * open are held for a short grace window, so a boost or teleport just before
 * the first kill of a trip still counts once that kill happens.
 *
 * <p>Ticks are counted by the caller. Not thread safe; use from the client thread.
 */
class SupplySession
{
    private static final int NO_KILL = Integer.MIN_VALUE;

    private int lastKillTick = NO_KILL;
    private final Deque<Pending> pending = new ArrayDeque<>();

    void reset()
    {
        lastKillTick = NO_KILL;
        pending.clear();
    }

    boolean isOpen(int tick, int timeoutTicks)
    {
        return lastKillTick != NO_KILL && tick - lastKillTick <= timeoutTicks;
    }

    /**
     * Record a task kill.
     *
     * @return supplies held in the grace window that now belong to the task;
     * empty when the session was already open
     */
    List<SupplyUsageTracker.Usage> onTaskKill(int tick, int timeoutTicks, int graceTicks)
    {
        boolean wasOpen = isOpen(tick, timeoutTicks);
        lastKillTick = tick;

        List<SupplyUsageTracker.Usage> claimed = new ArrayList<>();
        if (!wasOpen)
        {
            prune(tick, graceTicks);
            for (Pending p : pending)
            {
                claimed.addAll(p.used);
            }
        }
        pending.clear();
        return claimed;
    }

    /** Hold supplies used outside a session in case a task kill follows shortly. */
    void hold(int tick, int graceTicks, List<SupplyUsageTracker.Usage> used)
    {
        if (graceTicks <= 0 || used.isEmpty())
        {
            return;
        }
        pending.addLast(new Pending(tick, used));
        prune(tick, graceTicks);
    }

    private void prune(int tick, int graceTicks)
    {
        while (!pending.isEmpty() && tick - pending.peekFirst().tick > graceTicks)
        {
            pending.removeFirst();
        }
    }

    private static final class Pending
    {
        final int tick;
        final List<SupplyUsageTracker.Usage> used;

        Pending(int tick, List<SupplyUsageTracker.Usage> used)
        {
            this.tick = tick;
            this.used = used;
        }
    }
}

package com.papabald.slayerloot;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.util.Text;
import net.runelite.http.api.item.ItemPrice;

/**
 * Works out which supplies were used by comparing everything the player is
 * carrying from one tick to the next. Anything that went down counts as used.
 *
 * <p>Inventory, worn equipment, the rune pouch and the cannon's loaded
 * cannonballs are counted together, so moving an item between them (wielding
 * bolts, filling the pouch, loading the cannon) cancels out.
 *
 * <p>Items with a trailing "(n)" in their name (potion doses, jewellery
 * charges) are counted in those units rather than as whole items, so sipping a
 * 4-dose into a 3-dose is one dose used, priced as a quarter of the 4-dose.
 * Other items are grouped with their variants so a degrading or
 * recharging item swapping forms isn't read as the whole item being used.
 *
 * <p>Must only be used from the client thread.
 */
@Slf4j
class SupplyUsageTracker
{
    /** One supply that was used up: an item, how many, and their combined value. */
    static final class Usage
    {
        final int itemId;
        final String name;
        final int quantity;
        final long value;

        Usage(int itemId, String name, int quantity, long value)
        {
            this.itemId = itemId;
            this.name = name;
            this.quantity = quantity;
            this.value = value;
        }
    }

    private static final Pattern CHARGE_SUFFIX = Pattern.compile("^(.+?)\\s*\\((\\d+)\\)$");

    /** Cannon parts are set up and picked back up, not used up. */
    private static final Set<Integer> IGNORED_ITEMS = new HashSet<>(Arrays.asList(
        ItemID.TWPART1, ItemID.TWPART2, ItemID.TWPART3, ItemID.TWPART4
    ));

    private static final int[] RUNE_POUCH_TYPES = {
        VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
        VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6,
    };

    private static final int[] RUNE_POUCH_QUANTITIES = {
        VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
        VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6,
    };

    private final Client client;
    private final ItemManager itemManager;

    /** itemId -> quantity carried at the last measurement. Null until a baseline is taken. */
    private Map<Integer, Integer> baseline;

    /** itemId -> ticks left during which losses of that item are not counted (e.g. dropped). */
    private final Map<Integer, Integer> ignoredLosses = new HashMap<>();

    /** Lowercased charge-family name -> its fullest and single-charge variants (null if none found). */
    private final Map<String, ChargeVariants> chargeVariants = new HashMap<>();

    @Inject
    SupplyUsageTracker(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    /** Forget the baseline. The next {@link #measure()} takes a fresh one and reports nothing. */
    void reset()
    {
        baseline = null;
        ignoredLosses.clear();
    }

    /**
     * Take a fresh baseline without counting anything. Used while items are
     * moving for reasons other than being used: banking, shops, trades, dying.
     */
    void resync()
    {
        baseline = snapshot();
        ignoredLosses.clear();
    }

    /** Don't count the next few ticks of losses of this item, e.g. because the player dropped it. */
    void ignoreLossesOf(int itemId, int ticks)
    {
        if (itemId > 0)
        {
            ignoredLosses.put(itemManager.canonicalize(itemId), ticks);
        }
    }

    /**
     * Compare what is carried now against the last baseline and return what was
     * used up in between. The current state becomes the new baseline.
     */
    List<Usage> measure()
    {
        Map<Integer, Integer> current = snapshot();
        Map<Integer, Integer> previous = baseline;
        baseline = current;
        if (previous == null)
        {
            ignoredLosses.clear();
            return Collections.emptyList();
        }

        Set<Integer> ids = new HashSet<>(previous.keySet());
        ids.addAll(current.keySet());

        Map<String, Group> groups = new LinkedHashMap<>();
        for (int id : ids)
        {
            int delta = current.getOrDefault(id, 0) - previous.getOrDefault(id, 0);
            if (delta == 0 || (delta < 0 && ignoredLosses.containsKey(id)))
            {
                continue;
            }

            String name = itemName(id);
            Matcher charges = CHARGE_SUFFIX.matcher(name);
            Group group;
            int units;
            if (charges.matches())
            {
                String base = charges.group(1).trim();
                group = groups.computeIfAbsent("c:" + base.toLowerCase(Locale.ROOT), k -> new Group(base, true));
                units = delta * Integer.parseInt(charges.group(2));
            }
            else
            {
                group = groups.computeIfAbsent("v:" + ItemVariationMapping.map(id), k -> new Group(name, false));
                units = delta;
            }

            group.units += units;
            if (delta < 0 && -delta >= group.mostLost)
            {
                group.mostLost = -delta;
                group.lostItemId = id;
                group.lostItemName = name;
            }
        }

        ignoredLosses.replaceAll((id, ticks) -> ticks - 1);
        ignoredLosses.values().removeIf(ticks -> ticks <= 0);

        List<Usage> used = new ArrayList<>();
        for (Group group : groups.values())
        {
            // Only a net loss is a use. A net gain is loot or a restock, and a net
            // zero is an item changing form (degrading, recharging, swapping gear).
            if (group.units >= 0 || group.lostItemId <= 0)
            {
                continue;
            }

            Usage usage = group.byCharge ? chargeUsage(group) : itemUsage(group);
            if (usage != null && usage.value > 0)
            {
                used.add(usage);
            }
        }

        if (log.isDebugEnabled())
        {
            for (Usage u : used)
            {
                log.debug("supply used: {} x{} = {} gp", u.name, u.quantity, u.value);
            }
        }
        return used;
    }

    private Usage itemUsage(Group group)
    {
        int quantity = (int) -group.units;
        long value = (long) itemManager.getItemPrice(group.lostItemId) * quantity;
        return new Usage(group.lostItemId, group.lostItemName, quantity, value);
    }

    /** A dose or charge item: price per unit comes from its fullest tradeable variant. */
    private Usage chargeUsage(Group group)
    {
        int unitsUsed = (int) -group.units;
        String key = group.name.toLowerCase(Locale.ROOT);
        if (!chargeVariants.containsKey(key))
        {
            // Misses are cached too, so an unpriced family isn't searched again every tick.
            chargeVariants.put(key, findChargeVariants(group.name));
        }
        ChargeVariants variants = chargeVariants.get(key);

        if (variants == null)
        {
            // No tradeable variant to price against; fall back to the item that was used.
            Matcher m = CHARGE_SUFFIX.matcher(group.lostItemName);
            int perItem = m.matches() ? Math.max(1, Integer.parseInt(m.group(2))) : 1;
            long value = Math.round((double) itemManager.getItemPrice(group.lostItemId) * unitsUsed / perItem);
            return new Usage(group.lostItemId, group.lostItemName, unitsUsed, value);
        }

        long fullPrice = itemManager.getItemPrice(variants.fullestId);
        long value = Math.round((double) fullPrice * unitsUsed / variants.fullestCharges);
        // Shown as the 1-dose/1-charge item with a quantity of doses/charges used.
        int displayId = variants.singleId > 0 ? variants.singleId : group.lostItemId;
        return new Usage(displayId, group.name, unitsUsed, value);
    }

    private ChargeVariants findChargeVariants(String baseName)
    {
        int fullestId = -1;
        int fullestCharges = 0;
        int singleId = -1;
        for (ItemPrice candidate : itemManager.search(baseName))
        {
            Matcher m = CHARGE_SUFFIX.matcher(candidate.getName());
            if (!m.matches() || !m.group(1).trim().equalsIgnoreCase(baseName))
            {
                continue;
            }

            int charges = Integer.parseInt(m.group(2));
            if (charges == 1)
            {
                singleId = candidate.getId();
            }
            if (charges > fullestCharges && itemManager.getItemPrice(candidate.getId()) > 0)
            {
                fullestCharges = charges;
                fullestId = candidate.getId();
            }
        }
        return fullestId > 0 ? new ChargeVariants(fullestId, fullestCharges, singleId) : null;
    }

    private String itemName(int itemId)
    {
        ItemComposition composition = itemManager.getItemComposition(itemId);
        String name = composition == null ? null : composition.getName();
        return name == null ? "Item " + itemId : Text.removeTags(name);
    }

    private Map<Integer, Integer> snapshot()
    {
        Map<Integer, Integer> items = new HashMap<>();
        addContainer(items, InventoryID.INV);
        addContainer(items, InventoryID.WORN);
        addRunePouch(items);

        int loadedCannonballs = client.getVarpValue(VarPlayerID.ROCKTHROWER);
        if (loadedCannonballs > 0)
        {
            items.merge(ItemID.MCANNONBALL, loadedCannonballs, Integer::sum);
        }
        return items;
    }

    private void addContainer(Map<Integer, Integer> items, int containerId)
    {
        ItemContainer container = client.getItemContainer(containerId);
        if (container == null)
        {
            return;
        }

        for (Item item : container.getItems())
        {
            int id = item.getId();
            if (id <= 0 || item.getQuantity() <= 0 || IGNORED_ITEMS.contains(id))
            {
                continue;
            }
            // Noted and unnoted stacks are the same supply.
            items.merge(itemManager.canonicalize(id), item.getQuantity(), Integer::sum);
        }
    }

    private void addRunePouch(Map<Integer, Integer> items)
    {
        EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
        if (runeEnum == null)
        {
            return;
        }

        for (int slot = 0; slot < RUNE_POUCH_TYPES.length; slot++)
        {
            int type = client.getVarbitValue(RUNE_POUCH_TYPES[slot]);
            int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITIES[slot]);
            if (type <= 0 || quantity <= 0)
            {
                continue;
            }

            int runeId = runeEnum.getIntValue(type);
            if (runeId > 0)
            {
                items.merge(runeId, quantity, Integer::sum);
            }
        }
    }

    /** Net movement of one item (or dose/charge family) within a single measurement. */
    private static final class Group
    {
        final String name;
        final boolean byCharge;
        long units;
        int mostLost;
        int lostItemId = -1;
        String lostItemName;

        Group(String name, boolean byCharge)
        {
            this.name = name;
            this.byCharge = byCharge;
        }
    }

    private static final class ChargeVariants
    {
        final int fullestId;
        final int fullestCharges;
        final int singleId;

        ChargeVariants(int fullestId, int fullestCharges, int singleId)
        {
            this.fullestId = fullestId;
            this.fullestCharges = fullestCharges;
            this.singleId = singleId;
        }
    }
}

package com.papabald.slayerloot;

class TaskLootItem
{
    private final int itemId;
    private final String itemName;
    private int quantity;
    private long totalGeValue;
    private boolean excluded;

    TaskLootItem(int itemId, String itemName)
    {
        this.itemId = itemId;
        this.itemName = itemName;
    }

    int getItemId()
    {
        return itemId;
    }

    String getItemName()
    {
        return itemName;
    }

    int getQuantity()
    {
        return quantity;
    }

    long getTotalGeValue()
    {
        return totalGeValue;
    }

    boolean isExcluded()
    {
        return excluded;
    }

    void add(int qty, long geValue)
    {
        quantity += qty;
        totalGeValue += geValue;
    }

    void setExcluded(boolean excluded)
    {
        this.excluded = excluded;
    }

    void restore(int quantity, long totalGeValue, boolean excluded)
    {
        this.quantity = quantity;
        this.totalGeValue = totalGeValue;
        this.excluded = excluded;
    }
}

package com.papabald.slayerloot;

import java.time.Instant;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

class TaskLootRecord
{
    private final String taskKey;
    private final String taskName;
    private final Instant startedAt;
    private int kills;
    private boolean hidden;
    private final Map<Integer, TaskLootItem> items = new LinkedHashMap<>();
    private final Map<Integer, TaskLootItem> supplies = new LinkedHashMap<>();

    TaskLootRecord(String taskKey, String taskName)
    {
        this(taskKey, taskName, Instant.now(), 0);
    }

    TaskLootRecord(String taskKey, String taskName, Instant startedAt, int kills)
    {
        this.taskKey = taskKey;
        this.taskName = taskName;
        this.startedAt = startedAt;
        this.kills = kills;
    }

    String getTaskKey()
    {
        return taskKey;
    }

    String getTaskName()
    {
        return taskName;
    }

    int getKills()
    {
        return kills;
    }

    Collection<TaskLootItem> getItems()
    {
        return items.values();
    }

    void incrementKills()
    {
        kills++;
    }

    void addLoot(int itemId, String itemName, int qty, long geValue)
    {
        TaskLootItem item = items.computeIfAbsent(itemId, ignored -> new TaskLootItem(itemId, itemName));
        item.add(qty, geValue);
    }

    Collection<TaskLootItem> getSupplies()
    {
        return supplies.values();
    }

    void addSupply(int itemId, String itemName, int qty, long value)
    {
        TaskLootItem supply = supplies.computeIfAbsent(itemId, ignored -> new TaskLootItem(itemId, itemName));
        supply.add(qty, value);
    }

    void setSupplyExcluded(int itemId, boolean excluded)
    {
        TaskLootItem supply = supplies.get(itemId);
        if (supply != null)
        {
            supply.setExcluded(excluded);
        }
    }

    /** Value of supplies used on this task, leaving out any the user excluded. */
    long getSupplyCost()
    {
        return supplies.values().stream()
            .filter(supply -> !supply.isExcluded())
            .mapToLong(TaskLootItem::getTotalGeValue)
            .sum();
    }

    /** Actual loot value minus supplies used. */
    long getNetProfit()
    {
        return getActualProfit() - getSupplyCost();
    }

    void setItemExcluded(int itemId, boolean excluded)
    {
        TaskLootItem item = items.get(itemId);
        if (item != null)
        {
            item.setExcluded(excluded);
        }
    }

    long getGrossProfit()
    {
        return items.values().stream().mapToLong(TaskLootItem::getTotalGeValue).sum();
    }

    long getActualProfit()
    {
        return items.values().stream()
            .filter(item -> !item.isExcluded())
            .mapToLong(TaskLootItem::getTotalGeValue)
            .sum();
    }

    Instant getStartedAt()
    {
        return startedAt;
    }

    boolean isHidden()
    {
        return hidden;
    }

    void setHidden(boolean hidden)
    {
        this.hidden = hidden;
    }

    void putRestoredItem(int itemId, String itemName, int quantity, long totalGeValue, boolean excluded)
    {
        TaskLootItem item = new TaskLootItem(itemId, itemName);
        item.restore(quantity, totalGeValue, excluded);
        items.put(itemId, item);
    }

    void putRestoredSupply(int itemId, String itemName, int quantity, long totalValue, boolean excluded)
    {
        TaskLootItem supply = new TaskLootItem(itemId, itemName);
        supply.restore(quantity, totalValue, excluded);
        supplies.put(itemId, supply);
    }

    TaskLootRecord copy()
    {
        TaskLootRecord c = new TaskLootRecord(taskKey, taskName, startedAt, kills);
        c.hidden = hidden;
        for (TaskLootItem i : items.values())
        {
            c.putRestoredItem(i.getItemId(), i.getItemName(), i.getQuantity(), i.getTotalGeValue(), i.isExcluded());
        }
        for (TaskLootItem s : supplies.values())
        {
            c.putRestoredSupply(s.getItemId(), s.getItemName(), s.getQuantity(), s.getTotalGeValue(), s.isExcluded());
        }
        return c;
    }
}

